import {backend} from './backend-client.js'; import {store} from '../core/state-store.js'; const pid=()=>store.get('activeProject')?.id;
export const BookService={formats(){return backend.call('books.formats',{});},list(){return backend.call('books.list',{projectId:pid()});},get(id){return backend.call('books.get',{id,bookId:id});},save(data){return backend.call('books.save',{projectId:pid(),...data});},remove(id){return backend.call('books.delete',{id,bookId:id});},editions(bookId){return backend.call('books.editions.list',{projectId:pid(),bookId});},saveEdition(data){return backend.call('books.editions.save',{projectId:pid(),...data});},deleteEdition(id){return backend.call('books.editions.delete',{id,editionId:id});},chapters(bookId){return backend.call('books.chapters.list',{projectId:pid(),bookId});},saveChapter(data){return backend.call('books.chapters.save',{projectId:pid(),...data});},formatChapters(data){return backend.call('books.chapters.format',{projectId:pid(),...data});},coverSpec(data){return backend.call('books.cover.spec',{projectId:pid(),...data});},exportHtml(data){return backend.call('books.export.html',{projectId:pid(),...data},{timeoutMs:180000});}};
